import{_ as t,c as e,o as l,S as o}from"./chunks/framework.e41a6bf8.js";const s=JSON.parse('{"title":"样式简写属性（Style Props）","description":"","frontmatter":{},"headers":[],"relativePath":"components/styleProps/home.md","filePath":"components/styleProps/home.md","lastUpdated":1792997556000}'),d=[o('<h1 id="样式简写属性-style-props" tabindex="-1">样式简写属性（Style Props） <a class="header-anchor" href="#样式简写属性-style-props" aria-label="Permalink to &quot;样式简写属性（Style Props）&quot;">​</a></h1><p><code>syz-components</code> 所有组件都内置了一套 <strong>Mantine 风格的样式简写属性</strong>（Style Props）。你可以把常见的 CSS 样式直接写成组件的 prop，不必再写 <code>:style</code> 或单独套一层 <code>class</code>。</p><p>这套属性由全局 mixin 统一声明，<strong>所有组件都自动支持</strong>，组件内部已接好解析逻辑，业务代码直接传值即可。</p><h2 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h2><div class="language-vue vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#E1E4E8;">&lt;</span><span style="color:#85E89D;">template</span><span style="color:#E1E4E8;">&gt;</span></span>\n<span class="line"><span style="color:#E1E4E8;">  </span><span style="color:#6A737D;">&lt;!-- 外边距 12px、内边距 16px、浅蓝背景、蓝字 --&gt;</span></span>\n<span class="line"><span style="color:#E1E4E8;">  &lt;</span><span style="color:#85E89D;">s-flex</span><span style="color:#E1E4E8;"> </span><span style="color:#B392F0;">gap</span><span style="color:#E1E4E8;">=</span><span style="color:#9ECBFF;">&quot;small&quot;</span><span style="color:#E1E4E8;"> </span><span style="color:#B392F0;">m</span><span style="color:#E1E4E8;">=</span><span style="color:#9ECBFF;">&quot;12&quot;</span><span style="color:#E1E4E8;"> </span><span style="color:#B392F0;">p</span><span style="color:#E1E4E8;">=</span><span style="color:#9ECBFF;">&quot;16&quot;</span><span style="color:#E1E4E8;"> </span><span style="color:#B392F0;">bg</span><span style="color:#E1E4E8;">=</span><span style="color:#9ECBFF;">&quot;#f0f6ff&quot;</span><span style="color:#E1E4E8;"> </span><span style="color:#B392F0;">c</span><span style="color:#E1E4E8;">=</span><span style="color:#9ECBFF;">&quot;#1d4ed8&quot;</span><span style="color:#E1E4E8;">&gt;内容&lt;/</span><span style="color:#85E89D;">s-flex</span><span style="color:#E1E4E8;">&gt;</span></span>\n<span class="line"></span>\n<span class="line"><span style="color:#E1E4E8;">  </span><span style="color:#6A737D;">&lt;!-- 按钮：水平内边距 100px、水平外边距 100px --&gt;</span></span>\n<span class="line"><span style="color:#E1E4E8;">  &lt;</span><span style="color:#85E89D;">s-button</span><span style="color:#E1E4E8;"> </span><span style="color:#B392F0;">px</span><span style="color:#E1E4E8;">=</span><span style="color:#9ECBFF;">&quot;100&quot;</span><span style="color:#E1E4E8;"> </span><span style="color:#B392F0;">mx</span><span style="color:#E1E4E8;">=</span><span style="color:#9ECBFF;">&quot;100&quot;</span><span style="color:#E1E4E8;">&gt;按钮&lt;/</span><span style="color:#85E89D;">s-button</span><span style="color:#E1E4E8;">&gt;</span></span>\n<span class="line"></span>\n<span class="line"><span style="color:#E1E4E8;">  </span><span style="color:#6A737D;">&lt;!-- 标题：字重 400 --&gt;</span></span>\n<span class="line"><span style="color:#E1E4E8;">  &lt;</span><span style="color:#85E89D;">s-title</span><span style="color:#E1E4E8;"> </span><span style="color:#B392F0;">title</span><span style="color:#E1E4E8;">=</span><span style="color:#9ECBFF;">&quot;标题&quot;</span><span style="color:#E1E4E8;"> </span><span style="color:#B392F0;">fw</span><span style="color:#E1E4E8;">=</span><span style="color:#9ECBFF;">&quot;400&quot;</span><span style="color:#E1E4E8;"> /&gt;</span></span>\n<span class="line"><span style="color:#E1E4E8;">&lt;/</span><span style="color:#85E89D;">template</span><span style="color:#E1E4E8;">&gt;</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">template</span><span style="color:#24292E;">&gt;</span></span>\n<span class="line"><span style="color:#24292E;">  </span><span style="color:#6A737D;">&lt;!-- 外边距 12px、内边距 16px、浅蓝背景、蓝字 --&gt;</span></span>\n<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">s-flex</span><span style="color:#24292E;"> </span><span style="color:#6F42C1;">gap</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;small&quot;</span><span style="color:#24292E;"> </span><span style="color:#6F42C1;">m</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;12&quot;</span><span style="color:#24292E;"> </span><span style="color:#6F42C1;">p</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;16&quot;</span><span style="color:#24292E;"> </span><span style="color:#6F42C1;">bg</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;#f0f6ff&quot;</span><span style="color:#24292E;"> </span><span style="color:#6F42C1;">c</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;#1d4ed8&quot;</span><span style="color:#24292E;">&gt;内容&lt;/</span><span style="color:#22863A;">s-flex</span><span style="color:#24292E;">&gt;</span></span>\n<span class="line"></span>\n<span class="line"><span style="color:#24292E;">  </span><span style="color:#6A737D;">&lt;!-- 按钮：水平内边距 100px、水平外边距 100px --&gt;</span></span>\n<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">s-button</span><span style="color:#24292E;"> </span><span style="color:#6F42C1;">px</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;100&quot;</span><span style="color:#24292E;"> </span><span style="color:#6F42C1;">mx</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;100&quot;</span><span style="color:#24292E;">&gt;按钮&lt;/</span><span style="color:#22863A;">s-button</span><span style="color:#24292E;">&gt;</span></span>\n<span class="line"></span>\n<span class="line"><span style="color:#24292E;">  </span><span style="color:#6A737D;">&lt;!-- 标题：字重 400 --&gt;</span></span>\n<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">s-title</span><span style="color:#24292E;"> </span><span style="color:#6F42C1;">title</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;标题&quot;</span><span style="color:#24292E;"> </span><span style="color:#6F42C1;">fw</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;400&quot;</span><span style="color:#24292E;"> /&gt;</span></span>\n<span class="line"><span style="color:#24292E;">&lt;/</span><span style="color:#22863A;">template</span><span style="color:#24292E;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h2 id="属性一览" tabindex="-1">属性一览 <a class="header-anchor" href="#属性一览" aria-label="Permalink to &quot;属性一览&quot;">​</a></h2><h3 id="内边距与外边距" tabindex="-1">内边距与外边距 <a class="header-anchor" href="#内边距与外边距" aria-label="Permalink to &quot;内边距与外边距&quot;">​</a></h3><table><thead><tr><th style="text-align:center;">简写</th><th style="text-align:left;">对应 CSS</th><th style="text-align:center;">简写</th><th style="text-align:left;">对应 CSS</th></tr></thead><tbody><tr><td style="text-align:center;"><code>m</code></td><td style="text-align:left;"><code>margin</code></td><td style="text-align:center;"><code>p</code></td><td style="text-align:left;"><code>padding</code></td></tr><tr><td style="text-align:center;"><code>mt</code></td><td style="text-align:left;"><code>margin-top</code></td><td style="text-align:center;"><code>pt</code></td><td style="text-align:left;"><code>padding-top</code></td></tr><tr><td style="text-align:center;"><code>mb</code></td><td style="text-align:left;"><code>margin-bottom</code></td><td style="text-align:center;"><code>pb</code></td><td style="text-align:left;"><code>padding-bottom</code></td></tr><tr><td style="text-align:center;"><code>ml</code></td><td style="text-align:left;"><code>margin-left</code></td><td style="text-align:center;"><code>pl</code></td><td style="text-align:left;"><code>padding-left</code></td></tr><tr><td style="text-align:center;"><code>mr</code></td><td style="text-align:left;"><code>margin-right</code></td><td style="text-align:center;"><code>pr</code></td><td style="text-align:left;"><code>padding-right</code></td></tr><tr><td style="text-align:center;"><code>mx</code></td><td style="text-align:left;"><code>margin-left</code> + <code>margin-right</code></td><td style="text-align:center;"><code>px</code></td><td style="text-align:left;"><code>padding-left</code> + <code>padding-right</code></td></tr><tr><td style="text-align:center;"><code>my</code></td><td style="text-align:left;"><code>margin-top</code> + <code>margin-bottom</code></td><td style="text-align:center;"><code>py</code></td><td style="text-align:left;"><code>padding-top</code> + <code>padding-bottom</code></td></tr></tbody></table><h3 id="字体与文本" tabindex="-1">字体与文本 <a class="header-anchor" href="#字体与文本" aria-label="Permalink to &quot;字体与文本&quot;">​</a></h3><table><thead><tr><th style="text-align:center;">简写</th><th style="text-align:left;">对应 CSS</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:center;"><code>fs</code></td><td style="text-align:left;"><code>font-size</code></td><td style="text-align:left;">数字补 <code>px</code></td></tr><tr><td style="text-align:center;"><code>fw</code></td><td style="text-align:left;"><code>font-weight</code></td><td style="text-align:left;">如 <code>400</code>、<code>700</code>、<code>bold</code></td></tr><tr><td style="text-align:center;"><code>lh</code></td><td style="text-align:left;"><code>line-height</code></td><td style="text-align:left;">数字保持无单位（如 <code>1.5</code>），字符串原样</td></tr><tr><td style="text-align:center;"><code>ta</code></td><td style="text-align:left;"><code>text-align</code></td><td style="text-align:left;"><code>left / center / right</code></td></tr><tr><td style="text-align:center;"><code>tt</code></td><td style="text-align:left;"><code>text-transform</code></td><td style="text-align:left;"><code>uppercase / capitalize</code> 等</td></tr><tr><td style="text-align:center;"><code>td</code></td><td style="text-align:left;"><code>text-decoration</code></td><td style="text-align:left;"><code>underline</code> 等</td></tr><tr><td style="text-align:center;"><code>ff</code></td><td style="text-align:left;"><code>font-family</code></td><td style="text-align:left;">字体族</td></tr><tr><td style="text-align:center;"><code>lts</code></td><td style="text-align:left;"><code>letter-spacing</code></td><td style="text-align:left;">数字补 <code>px</code></td></tr></tbody></table><h3 id="尺寸与定位" tabindex="-1">尺寸与定位 <a class="header-anchor" href="#尺寸与定位" aria-label="Permalink to &quot;尺寸与定位&quot;">​</a></h3><table><thead><tr><th style="text-align:center;">简写</th><th style="text-align:left;">对应 CSS</th><th style="text-align:center;">简写</th><th style="text-align:left;">对应 CSS</th></tr></thead><tbody><tr><td style="text-align:center;"><code>w</code></td><td style="text-align:left;"><code>width</code></td><td style="text-align:center;"><code>h</code></td><td style="text-align:left;"><code>height</code></td></tr><tr><td style="text-align:center;"><code>miw</code></td><td style="text-align:left;"><code>min-width</code></td><td style="text-align:center;"><code>mih</code></td><td style="text-align:left;"><code>min-height</code></td></tr><tr><td style="text-align:center;"><code>maw</code></td><td style="text-align:left;"><code>max-width</code></td><td style="text-align:center;"><code>mah</code></td><td style="text-align:left;"><code>max-height</code></td></tr><tr><td style="text-align:center;"><code>pos</code></td><td style="text-align:left;"><code>position</code></td><td style="text-align:center;"><code>z</code></td><td style="text-align:left;"><code>z-index</code></td></tr><tr><td style="text-align:center;"><code>top</code></td><td style="text-align:left;"><code>top</code></td><td style="text-align:center;"><code>bottom</code></td><td style="text-align:left;"><code>bottom</code></td></tr><tr><td style="text-align:center;"><code>left</code></td><td style="text-align:left;"><code>left</code></td><td style="text-align:center;"><code>right</code></td><td style="text-align:left;"><code>right</code></td></tr><tr><td style="text-align:center;"><code>inset</code></td><td style="text-align:left;"><code>inset</code></td><td style="text-align:center;"><code>flex</code></td><td style="text-align:left;"><code>flex</code></td></tr></tbody></table><h3 id="背景与边框" tabindex="-1">背景与边框 <a class="header-anchor" href="#背景与边框" aria-label="Permalink to &quot;背景与边框&quot;">​</a></h3><table><thead><tr><th style="text-align:center;">简写</th><th style="text-align:left;">对应 CSS</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:center;"><code>bg</code></td><td style="text-align:left;"><code>background</code></td><td style="text-align:left;">颜色或完整背景值</td></tr><tr><td style="text-align:center;"><code>c</code></td><td style="text-align:left;"><code>color</code></td><td style="text-align:left;">文字颜色</td></tr><tr><td style="text-align:center;"><code>opacity</code></td><td style="text-align:left;"><code>opacity</code></td><td style="text-align:left;">如 <code>0.5</code></td></tr><tr><td style="text-align:center;"><code>bd</code></td><td style="text-align:left;"><code>border</code></td><td style="text-align:left;">如 <code>1px solid red</code></td></tr><tr><td style="text-align:center;"><code>bdt</code></td><td style="text-align:left;"><code>border-top</code></td><td style="text-align:left;">—</td></tr><tr><td style="text-align:center;"><code>bdb</code></td><td style="text-align:left;"><code>border-bottom</code></td><td style="text-align:left;">—</td></tr><tr><td style="text-align:center;"><code>bdl</code></td><td style="text-align:left;"><code>border-left</code></td><td style="text-align:left;">—</td></tr><tr><td style="text-align:center;"><code>bdr</code></td><td style="text-align:left;"><code>border-right</code></td><td style="text-align:left;">—</td></tr><tr><td style="text-align:center;"><code>br</code></td><td style="text-align:left;"><code>border-radius</code></td><td style="text-align:left;">数字补 <code>px</code></td></tr></tbody></table><h2 id="尺寸-token" tabindex="-1">尺寸 token <a class="header-anchor" href="#尺寸-token" aria-label="Permalink to &quot;尺寸 token&quot;">​</a></h2><p>长度类属性（<code>m</code> / <code>p</code> / <code>w</code> / <code>h</code> / <code>fs</code> / <code>br</code> / <code>inset</code> 等）除了数字和 CSS 长度，还支持组件库统一的尺寸 token（与 <code>gap</code> / <code>size</code> 一致）：</p><table><thead><tr><th style="text-align:center;">token</th><th style="text-align:left;">对应值</th><th style="text-align:center;">token</th><th style="text-align:left;">对应值</th></tr></thead><tbody><tr><td style="text-align:center;"><code>small</code></td><td style="text-align:left;"><code>8px</code></td><td style="text-align:center;"><code>large</code></td><td style="text-align:left;"><code>24px</code></td></tr><tr><td style="text-align:center;"><code>default</code></td><td style="text-align:left;"><code>16px</code></td><td style="text-align:center;">—</td><td style="text-align:left;">—</td></tr></tbody></table><p>例如 <code>pl=&quot;small&quot;</code> → <code>padding-left: 8px</code>，<code>m=&quot;default&quot;</code> → <code>margin: 16px</code>，<code>br=&quot;large&quot;</code> → <code>border-radius: 24px</code>。</p><h2 id="取值规则" tabindex="-1">取值规则 <a class="header-anchor" href="#取值规则" aria-label="Permalink to &quot;取值规则&quot;">​</a></h2><ol><li><strong>长度类属性</strong>（<code>m</code> / <code>p</code> / <code>w</code> / <code>h</code> / <code>fs</code> / <code>br</code> 等）：支持尺寸 token（<code>small</code> / <code>default</code> / <code>large</code>）、数字（自动补 <code>px</code>）或 CSS 长度字符串——<code>&quot;10&quot;</code> → <code>10px</code>、<code>&quot;1rem&quot;</code> 原样、<code>&quot;50%&quot;</code> 原样。</li><li><strong>关键词类属性</strong>（<code>fw</code> / <code>ta</code> / <code>tt</code> / <code>td</code> / <code>ff</code> / <code>pos</code> / <code>bg</code> / <code>c</code> / <code>bd</code> 等）：原样透传。</li><li><strong><code>lh</code></strong>（行高）：数字保持无单位（<code>1.5</code> 就是 <code>1.5</code>，不会变 <code>1.5px</code>），字符串原样。</li><li><strong><code>inset</code></strong>：支持 token 和数字（补 <code>px</code>，四边同值），多值字符串（如 <code>&quot;10px 20px&quot;</code>）原样透传。</li></ol><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li><strong>无需每个组件单独配置</strong>：样式简写由全局 mixin 统一声明，组件已内置解析与绑定，业务代码直接用。</li><li><strong>同名 prop 优先组件自身</strong>：少数组件自身已声明同名 prop（如 <code>s-flex</code> 的 <code>w</code> / <code>h</code> / <code>flex</code> / <code>gap</code>、<code>s-title</code> 的 <code>fs</code> 等），此时以组件自身语义为准，不会重复应用。</li><li><strong>数字写法</strong>：模板中直接写 <code>m=&quot;10&quot;</code>（字符串）或 <code>:m=&quot;10&quot;</code>（数字）都会得到 <code>10px</code>。</li></ul><h2 id="类型支持" tabindex="-1">类型支持 <a class="header-anchor" href="#类型支持" aria-label="Permalink to &quot;类型支持&quot;">​</a></h2><p>所有组件的 <code>.d.ts</code> 类型都已带上 <code>SybzStyleProps</code>，在 IDE 里写 <code>&lt;s-flex m=&quot;10&quot; fs=&quot;14px&quot; bg=&quot;#fff&quot; /&gt;</code> 会有完整的属性提示与类型校验。</p>',24)],a=t({name:"components/styleProps/home.md"},[["render",function(t,o,s,a,n,c){return l(),e("div",null,d)}]]);export{s as __pageData,a as default};
